"""Authored conversations. No generated dialogue or inferred relationship scores."""
def scene(title, opening, *choices):
    return {'title': title, 'opening': opening, 'choices': {k:{'label':label,'response':reply} for k,(label,reply) in zip(('curious','warm','candid'),choices)}}

PERSONAL = {
'mira':[
 scene('The correction in red', 'Mira has crossed out a note you left in a shared book. “I corrected the date. Then I realised I had corrected your description of the place as well.” She turns the page towards you. “That part was not an error.”',
 ('Ask what bothered her about the description','“You called it lonely. My notes called it disused.” Mira studies the two words. “I was pretending mine contained less of me. It did not.”'),
 ('Tell her you want both accounts on the page','“Side by side?” She fetches a fresh sheet instead of scraping yours clean. “That will make the catalogue untidy. I find I can survive it.”'),
 ('Say you want her to ask before changing your words','Her first reply comes quickly, then stops. “Yes. Accuracy did not give me ownership of the whole page.” She returns your pencil. “I will ask.”')),
 scene('An argument worth keeping','“I brought two copies,” Mira says. “One for each of us to disagree with.” The passage concerns whether a house remembers its inhabitants. She has already written a very firm no, then underlined a sentence that suggests otherwise.',
 ('Ask why that sentence survived her objections','“Listen: ‘The hollow in the stair remembered his father’s heel.’ A worn step can tell you where somebody walked. It cannot tell you whom they loved.” Mira taps her emphatic no. “I object to the claim. I like the sentence. Irritatingly, both are true.”'),
 ('Offer to read the opposing part aloud','You read the argument for a house remembering its owners: “Even the door resisted a stranger’s hand.” Mira answers, “Then oil the hinges before questioning the witness.” Your solemn reading breaks down. She writes requires two unconvincing actors in the margin.'),
 ('Tell her an argument need not end in agreement','“Then let us stop before I turn liking you into a requirement to persuade you.” She puts a bookmark between the two accounts. “Both remain.”')),
 scene('Two hands in the catalogue','Mira brings a small index headed with both your names. “I have left the descriptions unsigned in the main catalogue. But here, I want to remember who saw what.” She waits before putting your name beside an entry.',
 ('Ask her to keep track of how your views change','“Yes. Put the old reading beneath the correction, with a date. I want someone to be able to follow the mistake.” Mira rules a second line. “Including mine. Especially mine, before I develop a reputation for never making them.”'),
 ('Write a private note of appreciation beside hers','Mira reads it twice. “This is not a bibliographic category.” She folds the index carefully. “I will have to invent one.”'),
 ('Keep separate opinions, but share the collection','“Shared shelves, individual margins.” Mira nods. “We have finally designed a system capable of accommodating two people.”'))],
'tamsin':[
 scene('Who gets the last helping','Tamsin has saved a portion for someone who missed supper, then found three more empty chairs. “I keep saying there is enough. Sometimes I mean that I will have less.” She pushes her own plate back towards the table.',
 ('Ask when hospitality began to feel compulsory','“When people started thanking me for never needing to be asked.” Her ears lower. “It sounds lovely until you try to be unavailable.”'),
 ('Offer to sit and eat with her before sorting anything else','“While it is still warm?” She takes up her spoon. “That would be a surprisingly radical arrangement.” You let the empty chairs wait.'),
 ('Say she needs to tell you when there is not enough','“I can do that. But you must let an honest no remain a no, without making me present a defence.” She moves the serving dish within her own reach.')),
 scene('A place she did not set','Tamsin arrives carrying no tray. “I told the others I was coming to talk. Then I nearly brought something so it would count as a reason.” She looks at the seat beside you. “May this be the reason?”',
 ('Ask what she would choose for an evening of her own','“Guess the object, but the person answering is a very offended version of it. I shall be a kettle. Ask whether I have a handle and I will accuse you of judging appearances.” Tamsin folds her arms. “You get five questions. I intend to be difficult.”'),
 ('Make room and let her choose the conversation','“A market singer forgot the end of a ballad about a lost prince. First he married the prince to the wrong sister. Then he drowned him. Someone shouted that the wedding guests deserved their money back.” Tamsin laughs. “On the third attempt he made the prince a fisherman and kept both sisters. Terrible man. Excellent recovery.”'),
 ('Admit you sometimes mistake helpfulness for happiness','“Thank you for saying that.” Her tail stills. “I do enjoy looking after people. I want there to be room for the days when I do not.”')),
 scene('Her name on the invitation','A note from Tamsin invites you to a small evening at the table. Beneath the time she has written: I am a guest too. “It looked impertinent the first time,” she says. “Now I rather like it.”',
 ('Ask what she wants the evening to become','“I want to play the guessing game before anyone starts clearing plates. And I want to win once without being accused of knowing the answers because I arranged it.” She writes game first beneath her invitation. “You may choose the first object.”'),
 ('Accept, and promise her your company','“Good. That is what I meant to ask for.” She folds the note into your hand instead of returning to the kitchen.'),
 ('Suggest that both of you take turns asking for care','“Including the ungraceful requests?” She considers it. “Especially those, perhaps. We should not have to become charming before we can be tired.”'))],
'iona':[
 scene('The route she left off','Iona shows you a map with one road deliberately omitted. “It leads to somewhere I used to stay. Leaving it out was easier than explaining why I did not want to visit.” She has not brought a travelling case.',
 ('Ask whether she wants to tell you about the place','“The room was above a cobbler’s. A blue window, stairs that announced every visitor. The owner laid out my travelling coat before I had decided to leave.” Iona rests a hand on the map. “It was meant kindly. I got tired of being expected somewhere else.”'),
 ('Tell her a map need not be an invitation to return','“I was hoping you would understand the distinction.” She draws the road lightly, without an arrow at its end.'),
 ('Say you would rather hear a boundary than follow a misleading map','“Fair.” Iona writes private beside the road. “There. A truthful map, and a destination I am not offering.”')),
 scene('A letter without a departure','“I sent a letter,” Iona says. “I did not promise to come.” She seems pleased and uneasy in equal measure. “It is remarkable how often I used travel to avoid answering a question.”',
 ('Ask what she managed to say this time','“That I am well. That I stayed somewhere because I wished to. I did not turn either sentence into an itinerary.”'),
 ('Celebrate the small decision with her','“No grand announcement?” She smiles. “A cup raised to not packing. An occasion severely neglected by the poets.”'),
 ('Ask whether staying can become another way of avoiding things','“Of course.” She sits with the question instead of reaching for a map. “If you notice me doing that, ask. Do not decide for me.”')),
 scene('Somewhere she can be found','Iona places a forwarding address in her correspondence book: the castle. “Not forever by decree,” she says. “Just where I want a letter to find me now.”',
 ('Ask what makes an address feel like hers','“Somewhere people can send a letter about next month and expect me to care. I want to hear when the musicians move halls before I turn up at the wrong door.” She adds the castle to her address book. “And a shelf where my maps can lie flat.”'),
 ('Tell her you are glad she can be found here','She closes the book. “That is a much better welcome than asking how long I mean to stay.”'),
 ('Say belonging should leave the door open','“Then we agree on the architecture.” Iona offers you the pen. “An address, not a tether.”'))],
'aurelia':[
 scene('The alarm that was only wind','Aurelia admits she interrupted a conversation to check a noise that proved to be a loose shutter. “Nobody complained. That made it harder to come back and say I had been frightened.”',
 ('Ask what she thought she heard','“Three hard knocks, then a scrape,” Aurelia says. “I thought someone was forcing the door. The wind was lifting the shutter against its catch. I knew that when I saw it; my hands took longer to believe me.”'),
 ('Tell her she can return without an explanation','“Thank you. I left just as you were about to answer me.” Aurelia sits down and puts her gloves in her lap. “You were choosing between a room with a view and one with a good fire. I vote for the fire. A view seldom warms your toes.”'),
 ('Say constant vigilance can interrupt other people as well','Her wings draw close. “Yes. I want to protect the evening, and sometimes I am the one preventing it.” She asks to try again.')),
 scene('Who watches the watcher','“Would you tell me if I were doing too much?” Aurelia asks. “Not order me to rest. Tell me what you see.” She has chosen a chair facing the room instead of the entrance.',
 ('Ask what kind of reminder she could hear','“My name first. A question, not an accusation.” She tries the words herself: “Aurelia, are you still with us?”'),
 ('Offer the reminder quietly, between the two of you','“Quietly would help.” Her shoulders settle. “I would rather not become a household lesson in accepting help.”'),
 ('Admit you cannot always know when she needs it','“Then I must learn to say so.” She considers this with unusual seriousness. “I had hoped you might be able to guess. That was unfair.”')),
 scene('The shutter can wait','You and Aurelia are discussing whether a room needs a view or a good fire when the shutter taps. She glances at it, recognises the loose catch and turns back. “You were defending the view. I am still waiting to hear how it dries wet stockings.”',
 ('Ask which part felt different','“I recognised the same loose catch. There was no reason to interrupt you again.” She lays her gloves aside. “After we finish, I shall secure it. At present I have a much more pressing objection to your window.”'),
 ('Keep talking without making her into an achievement','“A mountain at sunset is very fine,” Aurelia concedes. “But after sunset you have a cold rectangle and a mountain you must take on trust.” She grins. “Give me a fire and a bad painting. I can admire the scenery all evening.”'),
 ('Say you will still speak up when something really needs attention','“Good. Rest should not depend on pretending nothing can happen.” She leaves the chair where it is.'))],
'neris':[
 scene('The cup that leaked','Neris presents a beautiful cup with a tiny crack. “I made it look finished before I admitted it was not.” She catches your glance at the cloth beneath it. “Yes. That is part of the presentation now.”',
 ('Ask why admitting the flaw mattered so much','“I wanted the rim this thin. It catches the light beautifully, but I cooled the base too quickly while fussing over it.” Neris turns the cup. “I noticed the crack before I showed you. That is the part I should have said first.”'),
 ('Admire the work while making room for the mistake','“You can like it and still notice the puddle.” She laughs, relieved. “A very useful combination.”'),
 ('Tell her you want honest warnings more than polished appearances','“Then: do not put anything precious in this cup.” She sets it between you. “There. We may now enjoy it honestly.”')),
 scene('A lesson neither of you prepared','Neris suggests teaching you the rhythm of a water song, then forgets the middle. “I should have practised.” She starts again and loses it in exactly the same place.',
 ('Ask her to explain the rhythm rather than perform it','Neris taps twice, pauses, then taps three times. “Two steps onto the landing, three down to the water. Keep the pause even if I forget the words.” You answer with the pattern. She comes in too early, laughs and starts again on your beat.'),
 ('Invent a new middle together','You suggest a duck who insists the river belongs to him. Neris sings, “The duck declared the river his; the fish replied, ‘Whose supper is this?’” She stops. “That does not rhyme nearly well enough to excuse how pleased I am.”'),
 ('Ask whether this needs to be a lesson at all','“Perhaps I wanted an excuse to sing with you.” She puts the imaginary lesson plan aside. “Would that have been enough to ask?”')),
 scene('The repaired seam','Neris brings back the cup with its crack sealed and the repair visible. “I kept it filled overnight on a dry cloth. No puddle this morning.” She turns the seam towards you. “Now I can admire the rim without concealing the base.”',
 ('Ask what she wants to make next','“A cup with enough room for a thumb through the handle. Beautiful on the shelf is a very short career.” She curls her hand around this one. “I will show you the first handle before I settle on the curve. You may be more difficult to please than a shelf.”'),
 ('Choose the repaired cup for your next shared drink','“Careful. That is how objects become impossible to throw away.” She looks pleased by the possibility.'),
 ('Say the seam does not need to become a moral','“Agreed. It is also simply a cup that leaked.” She fills it, checks the table, and lets that be enough.'))],

'sabine':[
 scene('A compliment too carefully made','“Your explanation would make even a particularly stubborn lock understand itself,” Sabine says, then winces. “That sounded as though I wanted you to fix one. I do not. You answered a difficult question without making the questioner feel foolish. I liked that.”',
 ('Ask what made the simpler version difficult','“It gives the listener more power. They can receive it badly, and I have no ornament behind which to retreat.”'),
 ('Accept the compliment without making her repeat it','“How mercifully undramatic.” She smiles. “I shall resist the urge to improve the sentence now that it has survived.”'),
 ('Say you sometimes cannot tell when she is being sincere','“That is useful to hear, if not flattering.” Sabine sets down her cup. “You may ask. I will try not to answer with another performance.”')),
 scene('The joke that missed','“At supper, someone carefully named all three forks,” Sabine says. “I called it a stirring speech on household defence. They stopped talking.” She folds her napkin. “They were trying to remember what they had been taught. I mistook nervousness for showing off.”',
 ('Ask whether she has spoken to the person privately','“Not yet. I keep improving the apology instead of making it.” She puts the napkin down. “‘You were trying to help. I made you the joke. I am sorry.’ That will do. If they have more to say, I need to hear it.”'),
 ('Tell her a plain apology can be enough to offer','“Offer. Not secure acceptance.” She repeats the distinction. “You have spared me an exceedingly polished mistake.”'),
 ('Ask her to leave room for the other person to remain annoyed','“An unpleasant but entirely reasonable privilege.” She nods. “I will not try to charm it out of them.”')),
 scene('No audience required','“I apologised,” Sabine says. “They were still annoyed. We nevertheless managed to discuss the weather.” She seems almost proud of the anticlimax.',
 ('Ask what she learned from the exchange','“They said they wanted to finish explaining the place settings next time. I had prepared myself for a denunciation. A request to stop interrupting was much harder to make a drama of.” She smiles ruefully. “I agreed.”'),
 ('Enjoy her company without asking for a polished conclusion','“I spent half this morning choosing a ribbon, then wore the first one. I should like you to admire its decisive simplicity.” Sabine laughs before you can answer. “Actually, I could not untie the other knot. My reputation survives only because I brought scissors.”'),
 ('Ask her to use that same plainness with you','“Very well. I enjoy your company. I occasionally find you exasperating. I would like both facts to be permitted.”'))],
'koharu':[
 scene('The repair nobody requested','Koharu has improved a chair someone liked as it was. “The joint was loose,” she says, then adds, “The cushion was not. I changed that because I thought mine was better.”',
 ('Ask what she noticed when they saw it','“They thanked me with the wrong face.” She turns a scrap of fabric between her fingers. “I had solved a problem they did not give me.”'),
 ('Offer to help her ask what they want restored','“I should do the asking.” She looks up. “But I would appreciate company afterwards, whatever the answer.”'),
 ('Tell her a gift can still take something away','Koharu is quiet. “Their right to like an inconvenient cushion.” She folds the fabric. “That is an irritatingly accurate way to put it.”')),
 scene('The part left deliberately crooked','Koharu shows you a repair plan with a crooked detail preserved. “They wanted this kept. I have annotated it so future clever people will not rescue it.”',
 ('Ask what history the detail carries','“A child measured it. They remember the measuring more than the chair.” She taps the note. “That changes what sound work means.”'),
 ('Tell her restraint belongs among her skills','“Do not tell the tools. They already think I neglect them when I sit down.” She leaves the plan unfinished for once.'),
 ('Ask how she will handle a truly unsafe sentimental repair','“Explain which part might fail. With a chair, I could brace the joint from beneath and leave the crooked rail visible, or replace the rail and return the old piece to its owner.” Koharu sketches both. “Sentiment will not support a person. A concealed brace might.”')),
 scene('Before she reaches for a tool','Koharu notices a worn clasp on your belongings and asks, “Would you like that repaired, or are you keeping it that way?” Her hand stays on the table.',
 ('Ask her to explain the options first','“I can replace the worn pin and keep the clasp,” Koharu says. “Or fit a larger clasp with a wider hinge. That will show, but it will take more strain. Which matters more to you: keeping this one, or carrying more weight?”'),
 ('Thank her for asking before offering your answer','“I am attempting a new craft. It appears to involve not already holding a screwdriver.” Her grin breaks the solemnity.'),
 ('Keep it as it is for now','“Then keep heavy things out of that pocket until we replace the pin.” Koharu puts her pencil away. “Now, would you settle something for me? Is the little wooden bird on my desk indignant or merely hungry? I meant to carve dignified.”'))],
'zahra':[
 scene('The story everyone expects','Zahra stops halfway through a tale about a broken anvil. “You know, I have other stories. People laugh so readily at the loud ones that I forget to tell them.”',
 ('Ask for one she rarely gets to tell','“A music-box lid kept falling shut before the tune ended. The owner wedged it with a spoon.” Zahra holds finger and thumb a little apart. “I filed a latch this small. When it worked, she put the spoon back in her tea and asked to hear the tune twice. That was a good afternoon.”'),
 ('Tell her she need not entertain you to keep your attention','“Dangerous offer. I know a great deal about rivet spacing.” Zahra smiles. “Too close and you perforate the plate; too far apart and the edge lifts. You may now explain why you thought this was preferable to the anvil story.”'),
 ('Admit you have sometimes encouraged the performance','“I enjoyed it too.” She leans back. “Let us not pretend I was dragged through every punchline. I would simply like more than one.”')),
 scene('A quiet boast','Zahra unwraps a small hinged wooden box. “Listen when I open it.” The hinge barely makes a sound. “I wanted the lid to stay where I put it, without a prop. The hinge took longer than the box.”',
 ('Ask her to show you the difficult part','“These two holes must share a centre. If one sits higher, the pin drags and the lid twists.” Zahra opens the box slowly. “I fitted the leaves against each other before fixing them to the wood. Less impressive than hammering. Considerably more difficult.”'),
 ('Let yourself be delighted by something small','She unwraps a second box, whose lid closes with a soft click. “This one has a catch. Same size, different problem. I wanted to know which sound you preferred.” Zahra opens both again, watching for your answer.'),
 ('Ask her to tell you when your teasing becomes repetitive','“I can do that. You may survive a direct comment.” She grins. “I will attempt not to reinforce the problem by bellowing it.”')),
 scene('Room for more than one story','At the next comfortable pause, Zahra asks, “Would you like the ridiculous story or the very particular one?” She seems equally ready to tell either.',
 ('Choose the very particular one','“A gate joint seized every winter. The pin was straight; the wet wood around it swelled.” Zahra draws the joint with a fingertip. “We had kept polishing the metal. Giving the wood room to move solved it. I lost an excellent argument about the pin.”'),
 ('Ask her which one she wants to tell','“The ridiculous one. We spent an hour moving an anvil through a narrow door before someone pointed out that the door could come off its hinges.” Zahra pauses. “I was holding the hinges. I had no defence.”'),
 ('Offer one of your own less impressive stories first','You admit that you have searched for something while carrying it. “Ah. I looked for my mallet with a mallet in my hand.” Zahra nods gravely. “Used it to point at the empty hook. Nobody in that room has permitted me to forget.”'))],
'fenna':[
 scene('A joke at the wrong moment','When you ask whether all her route notes are accurate, Fenna says, “Only the roads. I invented the rain.” Your silence stops her smile. “That was a fair question. I keep hoping a joke will get me out of admitting which turn I forgot to mark.”',
 ('Ask what she was trying not to say','“I was worried you meant none of my notes could be trusted. The missing mark is the left fork by the fallen oak.” Fenna reaches for the map. “I should have answered that before defending my entire reputation.”'),
 ('Let her try the question again without a punchline','“Are you asking about a particular turn, or whether I checked the whole route?” Fenna waits. “There. An actual question. The left fork needs adding either way.” She marks it and gives you the map to check.'),
 ('Say humour sometimes makes you feel she has not heard you','“I have heard you. I was trying to outrun the uncomfortable part.” She puts both hands flat on the table. “I can stay here instead.”')),
 scene('The pause she does not fill','Fenna allows an unusually long silence. “I have thought of four jokes,” she announces at last. “You are witnessing exceptional restraint.” Then she asks how you actually are.',
 ('Give her a complicated answer','You explain that you enjoy having people around and sometimes struggle to find time alone. “So when you shut the door, I should knock and accept ‘later’?” Fenna asks. “I can do that. I may complain to the door, but you need not answer it.”'),
 ('Thank her, then invite one of the four jokes','“Why did the guide refuse to give the rain directions? It was already getting everywhere.” Fenna watches your face. “Yes, that was the gentlest one. Imagine what I have spared you.”'),
 ('Tell her you do not need solemnity every time','“Good. I was beginning to fear a lifetime of meaningful nodding.” She checks your expression before laughing.')),
 scene('A question with no escape route','“Do you mind when I have no story ready?” Fenna asks. “I liked sitting with you the other day, but I kept wondering whether I was boring you.”',
 ('Tell her which quiet moment you remember','“When we sat here and I did not rush to fill the pause?” Fenna looks at the tabletop. “I remember wondering whether I should leave. Next time I could simply ask if you want company. It would save me a considerable amount of guessing.”'),
 ('Tell her you enjoy her company when she has no story ready','“Good. I was about to recycle the mule again.” Fenna pulls up a chair. “I would actually like to hear what you have been reading. I need recommendations from someone who can finish a book without losing it at an inn.”'),
 ('Say you want room for both honesty and nonsense','“A sensible arrangement. We must be careful not to let it damage our reputations.” The warmth comes before the joke this time.'))],
'kaede':[
 scene('An invitation she nearly refused','Kaede admits she declined a harmless game because she did not know its rules. “I said I was occupied. I was not. I disliked the thought of being clumsy in front of everyone.”',
 ('Ask who taught her that being a beginner was embarrassing','“Nobody in one lesson. Many people in little ones.” She turns a game piece over. “I have probably taught it too.”'),
 ('Offer to learn something unfamiliar alongside her','“You must actually be unfamiliar with it. No pretending so I may feel generous.” Her expression softens. “Then yes.”'),
 ('Say avoiding the game denied the others her company','“I had thought only about what they might see.” She sets the piece down. “Not what I was withholding.”')),
 scene('Losing without a lesson','Kaede has lost a practice game and begun analysing every move. Halfway through the explanation she stops. “Were you asking why I lost, or whether I enjoyed myself?”',
 ('Ask what was enjoyable before the analysis began','“I guarded the centre and left the edge open. My opponent moved around me instead of accepting the fight I had prepared.” Kaede places two pieces on the board. “I was furious for three seconds. Then I wanted to see it again.”'),
 ('Invite a rematch with no instruction afterwards','“A difficult condition.” She arranges the pieces anyway. “I accept, though I reserve the right to be delighted by a clever move.”'),
 ('Tell her you would like to play without being coached','“Thank you for making the request clear.” She withdraws her hand from your side of the board. “Your next move is yours.”')),
 scene('The move she cannot predict','Kaede asks you to choose the game this time. “I have decided I can be seen learning. I have not decided to enjoy losing. These are separate negotiations.”',
 ('Choose something that rewards curiosity over speed','You choose a guessing game: a hidden object, five questions, answers restricted to yes or no. “Does it fit in one hand?” Kaede asks immediately. She catches your smile. “Curiosity does not oblige me to begin inefficiently.”'),
 ('Choose an old favourite and enjoy the rivalry','Her answering smile is immediate. “Very well. Affectionate company is apparently compatible with wanting to beat you.”'),
 ('Suggest taking turns making up the rules','“One rule each, stated before the round. No changing a losing position by decree.” Kaede sets down two counters. “My rule: each of us must explain the opponent’s move before making our own. Now make that inconvenient for me.”'))],
'elowen':[
 scene('The advice you did not request','Elowen begins suggesting remedies before you have finished describing your day. She catches herself. “I am doing it again. You have offered me a conversation and I have opened a consultation.”',
 ('Ask whether she finds listening harder than helping','“Sometimes. Advice lets me believe I have changed the outcome.” She closes the little notebook. “Listening leaves more beyond my reach.”'),
 ('Tell her company would help today','“Then I shall attempt the difficult treatment of sitting beside you.” The joke is dry; the attention that follows is patient.'),
 ('Ask her to check before offering advice','“Yes. I would insist upon being asked in your place.” She puts the notebook away entirely.')),
 scene('A day she cannot improve','“I repotted the lemon balm, broke its saucer and knocked soil into my clean sleeves,” Elowen says. “Then I found the scissors I had spent an hour looking for, underneath the pot.” When you begin to answer, she lifts a hand. “Company first? I know where the dustpan is.”',
 ('Ask what she most wants you to understand','“I can put the plant right and still be cross about the afternoon. I liked that saucer. It was blue and exactly the right size.” Elowen sighs. “I do not need a better attitude towards broken pottery. I need to grumble for five minutes.”'),
 ('Stay with her without finding a bright side','“The soil went down my sleeve, not over it. That takes aim. Then I trod on the saucer while looking for the scissors.” Elowen inspects her cuff. “If you laugh, be honest about it. I shall probably join you once I have changed.”'),
 ('Tell her when you are unsure what to say','“That is considerably better than inventing certainty.” She offers you the spare cup. “We may both be unsure here.”')),
 scene('The question before the answer','“Would you like a thought, a practical suggestion, or simply an attentive person?” Elowen asks. “I am trying to stop treating those as interchangeable.”',
 ('Ask for a thought you can consider without following','“An offer of help can become another decision someone is too tired to make,” Elowen says. “I sometimes give people three choices when they asked for a cup of water. Perhaps I should start by listening to the request.” She asks whether you have noticed her doing it.'),
 ('Choose the attentive person','“Available immediately.” She moves the notebook out of the way and asks you to begin wherever you wish.'),
 ('Say you may change your mind halfway through','“Then tell me when you do.” She smiles. “A conversation need not submit its final requirements in advance.”'))],
'nyssara':[
 scene('The mark beneath the warning','Nyssara finds that someone has copied a warning beside her maker’s mark. “The warning is sensible. Its placement suggests my name is the dangerous part.” She speaks evenly, leaving you room to answer carefully.',
 ('Ask which part she wants changed','“Move the warning to the working instructions. Keep my name beside what I made.” She points to each separately. “Two different pieces of information.”'),
 ('Tell her you will hear the distinction without asking her to soften it','“Good. I would rather spend the evening talking than persuading you that this is worth mentioning.”'),
 ('Ask how to raise a real concern without repeating the mistake','“Name the behaviour or the enchantment. Be specific. I can answer a question about my work; I cannot repair a suspicion attached to my existence.”')),
 scene('An explanation offered freely','Nyssara brings a harmless practice pattern. “I want to show you how I see it. This is an invitation, not a defence.” She waits for you to draw the first line.',
 ('Ask what detail she notices first','“This branch returns to the same junction. Follow it with your finger: you arrive back here without reaching the exit.” Nyssara taps the drawing. “The maker wrote ‘repeat until complete’ but never defined complete. I want an apprentice to be able to spot that before copying it.”'),
 ('Tell her you enjoy seeing her absorbed in her craft','She glances up, momentarily less composed. “That is an agreeable reason to be watched.” Then she returns to the pattern, making room for your hand.'),
 ('Ask her to tell you when your questions become intrusive','“I will. And you may accept the boundary without turning the remainder of the evening into an apology.”')),
 scene('Her name, correctly placed','The revised label carries Nyssara’s name beside the work and clear instructions beneath. “Ordinary credit,” she says. “I find I am becoming quite ambitious about being treated ordinarily.”',
 ('Ask what she wants to be known for next','“A set of examples an apprentice can check without needing me beside them. One sound design, one fault, and a way to distinguish them.” Nyssara smiles. “I also wish to be known for an excellent joke. The audience is proving harder to train.”'),
 ('Invite her company without making the label the whole evening','“Gladly. I am reading a mystery in which the witness heard a clock through two locked doors. The author has spent three pages describing the carpet and none explaining that.” Nyssara sets aside her pattern. “Carelessness, or the clue? I am trying to give her the benefit of the doubt.”'),
 ('Say you may still disagree about her work','“I should hope so. Respect which cannot survive a technical objection would be a very poor enchantment.”'))],
'sylva':[
 scene('The cutting she did not offer','Sylva notices someone assuming that any flourishing plant can spare a cutting. “It may be able to. That does not mean it has been offered.” A leaf at her wrist curls as she considers how to explain.',
 ('Ask how she distinguishes tending from taking','“This plant has three strong stems. Taking two would leave too little leaf to feed it while it recovers.” Sylva touches the pot. “I also kept it for its shape. Even if taking one were harmless, I would want to choose whether to give it.”'),
 ('Tell her she can want something left alone','“Without proving it is fragile?” She looks relieved. “I would like that to be an ordinary reason.”'),
 ('Ask how people can learn without being afraid to touch anything','“By asking, and by being told clearly.” Her voice warms. “A garden of unspoken prohibitions would be a lonely place.”')),
 scene('A season that looks like nothing','Sylva has kept a bare pot where visitors expect a blossom. “Everyone offers to replace it. It is resting.” She smiles wryly. “I am considering a little sign for myself as well.”',
 ('Ask what rest looks like to her','“Warm stone, honey water, and looking at colours without checking which leaf belongs to which plant.” Sylva leans back. “I would like to arrange fallen leaves into a picture. Nobody gets to ask whether the arrangement would germinate.”'),
 ('Share the quiet without asking when the pot will flower','Sylva points to the strip of sunlight on the wall. “That looks yellow until you put this copper leaf beside it.” You compare the colours as the light shifts. She prefers the copper against the grey stone; you can at least agree it disappears against the pot.'),
 ('Say she will need to tell you when she wants solitude','“Yes. I cannot expect you to read a leaf correctly every time.” She lifts her wrist. “Sometimes this means only that I am cold.”')),
 scene('A gift she chose to give','Sylva offers you a pressed leaf, carefully wrapped. “This one I wanted to share. I thought the difference deserved something you could hold.”',
 ('Ask which moment the leaf preserves','“The wall was grey until the sun reached it,” Sylva says. “Then the leaf cast a red patch through a crack in the shutters. I stayed to watch it move. That was the first thing I wanted to tell you.”'),
 ('Accept it as a personal gift','“Keep it however you like.” She smiles. “You need not turn appreciation into excellent plant care.”'),
 ('Ask whether you may someday give it to someone else','She considers it. “Yes. Tell them where it came from. A gift may continue travelling after I have finished making it.”'))]
}

# Each pair has an introduction, a negotiated change, and a later outcome.
# The final opening includes an authored branch based on the preceding choice.
PAIRS = {}
def pair(key, people, label, rows, branches):
    PAIRS[key]={'participants':people,'label':label,'scenes':rows,'branches':branches}

pair('mira-tamsin',['mira','tamsin'],'Making room for different kinds of care',[
 scene('The recipe in the margin','Mira has tidied a recipe that Tamsin remembers by feel. “A generous handful is not a measurement,” Mira says. “It is if you know whose hand,” Tamsin replies. Neither wants to surrender the page.',
 ('Ask each of them to explain what the other version loses','Mira wants a stranger to reproduce it. Tamsin wants the cook to notice the dough. “Then we have two readers,” Mira concedes. “Perhaps two kinds of instruction.”'),
 ('Suggest trying the recipe together before editing it','Tamsin offers the bowl; Mira offers the pencil. Their first discovery is that neither object belongs anywhere near the other when the stirring becomes enthusiastic.'),
 ('Ask them to keep both versions without declaring a winner','“Facing pages,” Mira proposes. “And no quietly correcting mine at night,” Tamsin adds. Mira accepts the condition.')),
 scene('Flour on the index cards','Tamsin reports that the written recipe worked until the weather changed. Mira reports that “you will know” was unhelpful precisely when she did not. They arrive with the same slightly embarrassed smile.',
 ('Help them record the signs a beginner can observe','“Smooth enough that it no longer tears when folded,” Tamsin says. “Slightly tacky, not clinging in a lump to your fingers.” Mira writes both down. “And if it still tears?” “Rest it before kneading again.” Mira adds that instruction beneath the signs.'),
 ('Encourage them to make the experiment a regular shared evening','“Only if we may make something we cannot catalogue afterwards,” Tamsin says. “I can probably tolerate cake,” Mira replies.'),
 ('Suggest they choose which version to use each time','They put both cards in the box. “An invitation to choose,” says Mira. “Rather than a test you can fail,” Tamsin adds.')),
 scene('A note in two hands','A flour-marked card appears on the table. Mira’s small writing shares it with Tamsin’s broad corrections. “We have both become rather opinionated about bowls,” Tamsin tells you.',
 ('Ask what they learned about one another','Mira says Tamsin notices hesitation before a question is spoken. Tamsin says Mira asks questions she had stopped remembering were difficult. They look pleased to have been noticed accurately.'),
 ('Enjoy being invited into their new shared joke','“Do not say generous handful,” Mira warns you. Tamsin raises both hands with exaggerated innocence. You have arrived in the middle of a friendship with its own vocabulary.'),
 ('Let them keep the project theirs','They return to their argument about bowls without needing you to settle it. This time you can hear the pleasure beneath the disagreement.'))],
 {'curious':'Their next card describes texture as carefully as quantity; both have signed the explanation.','warm':'They have begun keeping one evening for experiments, including failures nobody has to serve.','candid':'Two complete recipes remain in the box, and choosing one has stopped being a declaration of loyalty.'})

pair('iona-fenna',['iona','fenna'],'Routes, stories and reliability',[
 scene('The scenic shortcut','Fenna calls a route a shortcut. Iona points out that it is longer. “But the journey feels shorter,” Fenna says. “An excellent distinction to tell someone before they depart,” Iona answers.',
 ('Ask them to distinguish fast from pleasant','Iona draws a clock beside one route. Fenna draws a cup beside the other. “Now I know which kind of late I am choosing,” Iona says.'),
 ('Invite Fenna to tell the story of the detour','“The gate lifted off its catch if you pushed, but jammed if you pulled,” Fenna says. “The owner watched me struggle, brought tea, then told me.” Iona raises an eyebrow. “Please mark which side to push. I prefer my hospitality without an entrance examination.”'),
 ('Support giving travellers the inconvenient facts first','Fenna nods. “Longer road, better company. I can sell that honestly.” Iona relaxes at the word honestly.')),
 scene('Waiting at the wrong turning','Iona says she waited while Fenna stopped to talk. Fenna had assumed the delay was obvious. “I enjoy surprises,” Iona says. “Less so when I think someone is missing.”',
 ('Help them agree on a meeting place before wandering','They choose a simple rule: name where to meet and say when plans change. Fenna calls it an arrangement with room to breathe.'),
 ('Ask Fenna to explain why she stops for people','“Because they may not ask twice.” Iona hears the care behind the wandering. “Then tell me. Sometimes I would like to stop too.”'),
 ('Ask Iona to say when she would rather travel separately','“I can do that without calling her unreliable,” Iona says. “And I can hear it without calling her dull,” Fenna replies.')),
 scene('Two marks on the map','Fenna and Iona bring you a map with separate marks for places to reach and places to linger. “Nobody has been officially declared dull,” Fenna reports.',
 ('Ask how the arrangement is working','Iona admits she has discovered a good bench. Fenna admits she has discovered the relief of knowing someone will be where they said. Neither lets the other make too much of it.'),
 ('Ask to hear about their favourite unplanned stop','Iona chooses the bench beside a fiddle player who accepted requests but ignored their tempo. Fenna chooses the inn whose owner let wet travellers sit nearest the stove. “You stayed for three tunes,” Fenna says. “You stayed for three cups,” Iona answers. Neither denies it.'),
 ('Point out that they do not need identical travelling habits','“Fortunately,” they say together. The simultaneous answer amuses them more than either intended.'))],
 {'curious':'A meeting place is written clearly on the next route, leaving the paths between it open.','warm':'Their latest detour was agreed together; Iona has added the name of the person they stopped to see.','candid':'One recent journey was made separately, and their accounts became the evening’s conversation.'})

pair('aurelia-kaede',['aurelia','kaede'],'Respect beyond readiness',[
 scene('An exercise that never ended','Kaede has been discussing practice after Aurelia believed the session was over. “I put the equipment down,” Aurelia says. “I thought that meant I could stop being evaluated.” Kaede looks genuinely startled.',
 ('Ask them to say explicitly when practice has ended','They settle on a plain ending, spoken aloud. Kaede admits she can continue a lesson entirely inside her own head and expect everyone else to follow.'),
 ('Ask what each enjoys about company outside practice','Aurelia likes dry stories. Kaede likes games she pretends not to take seriously. Both seem surprised that the other might supply either.'),
 ('Say unsolicited instruction can feel like a judgement','Kaede accepts the point without explaining her good intentions again. “Then I will ask before offering the next correction.”')),
 scene('The missing invitation','Kaede invites Aurelia to sit with her, then adds that there will be no practice discussion. “I had not realised an invitation needed that clause,” Aurelia says. “I am learning that some of mine do,” Kaede replies.',
 ('Ask them to find a subject neither has mastered','They choose an unfamiliar board game. Aurelia discovers that Kaede reads rules with the suspicion usually reserved for ambushes.'),
 ('Suggest swapping an embarrassing harmless story','Aurelia describes saluting a coat in a dark doorway. Kaede answers, “I demonstrated a turn, slipped, and landed in a basket.” Aurelia asks whether she saluted it afterwards. Kaede looks offended for a moment, then laughs. “It had certainly earned my respect.”'),
 ('Let them decide the evening without a facilitator','You excuse yourself from choosing. Their first shared decision is to leave the equipment exactly where it is.')),
 scene('Companions off duty','Aurelia and Kaede are already talking when you arrive. Neither stands. “We have declared the chairs outside the training jurisdiction,” Kaede explains.',
 ('Ask what has become easier between them','“Not needing to be impressive,” Aurelia says. Kaede takes a moment, then agrees without qualifying it.'),
 ('Join their gentle argument about the game','Aurelia accuses Kaede of tactical cup placement. Kaede maintains that a stable drink is not a military doctrine.'),
 ('Remind them that they can still enjoy practising together','“Certainly,” Kaede says. “We have simply acquired a second subject.” Aurelia adds that it is a considerable relief.'))],
 {'curious':'The unfamiliar game is still on the table, with corrections to the rules in two equally baffled hands.','warm':'An insignificant coat has become an enduring private joke, which Aurelia now tells better than Kaede.','candid':'They have begun inviting one another directly; their company no longer depends on your arrangements.'})

pair('sabine-elowen',['sabine','elowen'],'Candour and tact',[
 scene('A truth wrapped too tightly','Sabine thinks Elowen gave a blunt answer to a nervous question. Elowen thinks Sabine’s kinder version concealed the answer. “A truth still needs a door,” Sabine says. “And an address,” Elowen replies.',
 ('Ask what the nervous person actually needed to know','“They asked whether the ward was ready to use,” Elowen says. “I answered no.” Sabine adds, “I explained that the repair was going well.” They pause. Elowen tries again: “Not yet. The gap must be closed before it is lit.” Sabine nods. “That is the whole answer.”'),
 ('Invite each to rewrite one sentence in the other’s style','Sabine tries, “Not yet; the chalk line still has a gap.” Elowen tries, “We regret to inform you of a discontinuity—” Sabine laughs, then catches herself. “Sorry. Say the first version. Then explain what happens next. Kindness does not require an official seal.”'),
 ('Say kindness should not require guessing the answer','Sabine agrees to stop before tact becomes fog. Elowen agrees to distinguish clarity from abruptness.')),
 scene('An honest answer, gently delivered','Elowen brings a draft reply to Sabine. “Will you tell me where this becomes unnecessarily sharp?” Sabine reads it without picking up a pen. “Would you like suggestions or a rewrite?”',
 ('Encourage suggestions that leave the original author in control','Elowen keeps the pen. Sabine points to “As I have already explained.” “Does that help them repair the line?” Elowen crosses it out. “No. It announces that I am irritated.” She keeps the instruction that follows: leave the lamp unlit until the gap is closed.'),
 ('Ask them to read it aloud together','Elowen reads, “Do not light the lamp. The chalk line still has a gap.” Sabine asks her to pause between the warning and the explanation. “There. It sounds like two things somebody can hear, instead of one breath of exasperation.”'),
 ('Ask them to keep the difficult fact unmistakable','They put the answer in the first sentence and the explanation afterwards. Sabine observes that directness need not arrive alone.')),
 scene('No translation required','Sabine and Elowen disagree about a letter, then each summarises the other’s concern accurately. They look at you. “That was rather better than last time,” Elowen says.',
 ('Ask what helped them hear each other','“She stopped assuming precision meant indifference,” Elowen says. “She stopped assuming tact meant dishonesty,” Sabine answers.'),
 ('Enjoy their increasingly dry shared humour','Elowen says, “Tea at four?” Sabine begins, “Your esteemed presence beside a beverage of considerable—” Elowen hands Sabine an imaginary cold cup. Sabine stops. “A devastating editorial comment.”'),
 ('Say they need not merge their voices','“Thank goodness,” Sabine says. Elowen nods. “I have only just become comfortable with my own.”'))],
 {'curious':'Elowen still holds the pen; Sabine’s questions have replaced her habitual silent revisions.','warm':'Reading aloud has become a shared ritual, and both have developed a merciless ear for overlong sentences.','candid':'Their replies now lead with the answer, followed by enough care to help the reader receive it.'})

pair('neris-elowen',['neris','elowen'],'Different temperatures, shared space',[
 scene('The argument about the window','Neris opens the window; Elowen closes it. They have repeated the exchange twice before either speaks. “I thought you had not noticed,” Neris says. “I noticed,” Elowen replies.',
 ('Ask each to describe what would make the room comfortable','The problem turns out to be a draught at one chair and stagnant air at another. Moving the chairs seems embarrassingly simple once both descriptions are heard.'),
 ('Invite them to laugh at the silent window contest','“A devastating tactical stalemate,” Elowen says. Neris concedes that the window has shown admirable neutrality.'),
 ('Say neither should silently decide for the whole room','They agree to ask before adjusting it again. Nobody claims that being uncomfortable gave her the only legitimate vote.')),
 scene('A cup cooled too soon','Neris cooled a drink that Elowen meant to sip slowly. Elowen added hot water from the kettle. “We appear to have invented a very elaborate way not to ask a question,” Neris says.',
 ('Suggest asking before helping, even with familiar preferences','They practise with excessive ceremony until the joke gives way to an ordinary question. “How do you want yours?” turns out to be enough.'),
 ('Encourage them to share the table with differently prepared drinks','Two cups arrive at different temperatures. Elowen calls it a scandalous failure of uniformity and looks perfectly content.'),
 ('Ask them to leave one another’s cups alone','“A clear jurisdiction,” Neris says. Elowen marks an imaginary border around her saucer. Both respect it.')),
 scene('The window left halfway','You find the two of them sharing a table with the window ajar. “We have not solved the climate,” Elowen says. “Only the conversation about it,” Neris adds.',
 ('Ask which assumption was hardest to stop making','Neris had assumed comfort was obvious. Elowen had assumed asking would become an argument. They are amused by how thoroughly each had been wrong.'),
 ('Join them with your own preference stated plainly','They make room without treating your preference as a tie-breaking vote. Three people are allowed three different cups.'),
 ('Leave the compromise open to revision','“Naturally,” Neris says. “The weather has declined to sign a permanent agreement.” Elowen reaches for her own cup and no one else’s.'))],
 {'curious':'They ask first now, including on days when they are almost certain of the answer.','warm':'Two deliberately different drinks have become their preferred way of sharing a table.','candid':'The saucer borders remain a joke, but the habit of leaving another person’s cup alone is real.'})

pair('koharu-zahra',['koharu','zahra'],'Giving and receiving practical trust',[
 scene('The borrowed chisel','Zahra borrowed a chisel and returned it sharpened differently. Koharu notices at once. “I made it better,” Zahra begins, then hears herself. “For my hand, perhaps.”',
 ('Ask Koharu to explain the difference in use','Koharu rests the chisel against the wood. “The steeper bevel lifts it sooner. I use this one to reach a shallow corner.” Zahra tries the angle. “I sharpened it for cutting deeper. I should have asked which job it had.”'),
 ('Suggest they compare their favourite tools','Zahra likes a broad grip that does not turn in her palm. Koharu wants a narrower one she can guide with her fingertips. They swap tools and immediately change back. “Excellent,” Koharu says. “We have established that your favourite remains yours.”'),
 ('Ask them to agree that borrowing does not include alteration','Zahra agrees. Koharu adds that a question would have been welcome. The disagreement ends with a rule both can actually remember.')),
 scene('A tool made for another hand','Zahra brings a sketch, not a finished gift. “I thought I might ask first this time.” Koharu looks it over and asks for a smaller grip. Zahra changes the drawing immediately.',
 ('Ask them to test the shape together before making it','Koharu tries a scrap-wood grip and catches her thumb on its shoulder. Zahra marks the spot. “Smaller there too.” Koharu nods. “I would rather discover that in scrap than complain politely about the finished gift.”'),
 ('Ask why Zahra wanted to make the gift','“Because I watch her work and wanted to make it easier.” Koharu’s reply is quieter than her usual workshop voice. “I noticed.”'),
 ('Make room for Koharu to decline the design','Koharu considers the offer rather than reassuring Zahra. She chooses to accept, with changes. Zahra treats the changes as useful information.')),
 scene('The grip with two makers','Koharu brings the finished grip to the table. “Her patience,” she says, indicating Zahra, “was the most surprising material.” Zahra claims it was exceptionally expensive.',
 ('Ask what each contributed','Zahra names Koharu’s exacting questions. Koharu names Zahra’s willingness to start again. Neither pretends that collaboration meant agreeing on the first sketch.'),
 ('Invite them to tell the least dignified part of making it','“The first grip suited neither of us,” Zahra says. Koharu adds, “She had averaged our measurements. We had designed it for a third person.” Zahra lifts the finished tool. “We agreed that recruiting someone to fit it was the less economical solution.”'),
 ('Let the gift remain between them','They pass the tool back and forth, discussing a detail you do not need to judge. Their trust has a practical life beyond your approval.'))],
 {'curious':'A scruffy prototype hangs beside the finished grip as a reminder that testing together saved time.','warm':'Koharu has begun noticing small ways to make Zahra’s work easier in return, always asking first.','candid':'The accepted changes remain visible in the sketch; neither has erased the evidence of negotiation.'})

pair('nyssara-sylva',['nyssara','sylva'],'Patterns that leave room to grow',[
 scene('The line that would not stay straight','Nyssara draws an elegant support pattern around a climbing stem. Sylva turns the page. “It will want to grow there.” Nyssara studies the awkward bend. “Then my elegant pattern has failed its first resident.”',
 ('Ask them to design for change rather than the current shape','Nyssara leaves adjustable junctions. Sylva points out where she cannot predict the direction. Uncertainty becomes part of the drawing.'),
 ('Ask what each finds beautiful in the other’s approach','Sylva admires the care in a deliberate line. Nyssara admires the stem’s unembarrassed refusal to follow it. Both seem surprised by the answer.'),
 ('Ask whether the plant needs an enchantment at all','They put the design aside and examine the ordinary support first. Nyssara is the one who says it may be sufficient.')),
 scene('An experiment allowed to fail','Sylva reports that the stem chose an unexpected direction. Nyssara says, “I had a revised drawing ready. Then I realised I was making an argument, not a support.”',
 ('Suggest an adjustable ordinary frame before further magic','They choose something that can be moved by hand. Nyssara labels it provisional with visible satisfaction.'),
 ('Invite them to observe it together without fixing it today','Sylva finds a new tendril behind the upright; Nyssara points out that it has reached the rough wood rather than her polished ring. “It prefers a grip to an elegant surface,” Nyssara says. “A defensible preference.” Sylva laughs and asks her to write that beside the drawing.'),
 ('Let Sylva choose whether the experiment continues','Sylva asks to stop the enchantment trial and keep the conversation. Nyssara agrees without making the unfinished diagram into a debt.')),
 scene('A shape neither predicted','Nyssara and Sylva show you a sketch with a generous blank area. “Reserved for developments,” Nyssara says. “Or for leaving well enough alone,” Sylva adds.',
 ('Ask how their definition of a good design changed','Nyssara says a good design can admit what it does not know. Sylva says careful planning need not be a promise to control everything.'),
 ('Ask to hear about their conversations away from the project','“She called a vine sarcastic,” Nyssara says. Sylva points to the abandoned support drawing. “It climbed every upright except the one you labelled ideal.” Nyssara considers. “Contrary, perhaps. Sarcasm would require a remark.” Sylva writes nice frame beside the sketch.'),
 ('Say the friendship need not produce a finished object','“An excellent outcome specification,” Nyssara says. Sylva laughs and draws a leaf in the margin, outside every planned line.'))],
 {'curious':'The ordinary frame can be adjusted without anyone having to defend a theory first.','warm':'Watching the plant has become an excuse to meet; they now sometimes forget to discuss it.','candid':'The enchantment diagram remains unfinished by agreement, while their visits continue.'})

pair('mira-zahra',['mira','zahra'],'Whose expertise counts',[
 scene('The word for what her hands know','Mira uses a technical term for a joint Zahra has made for years. Zahra supplies another name. “I thought that was a local expression,” Mira says. “It is. Local to people who make it,” Zahra replies.',
 ('Ask where both names come from','Mira finds a printed source; Zahra recalls the workshop where she learned. The accounts describe the same useful idea travelling by different routes.'),
 ('Invite a demonstration in exchange for the written explanation','Zahra braces the wood before moving the tool. Mira checks the diagram. “The drawing shows neither the brace nor the hand holding it.” Zahra nods. “Follow it exactly and the piece turns with the blade.” Mira writes hold the work securely before the first cutting step.'),
 ('Ask Mira not to rank knowledge by whether it was printed','Mira nods. “I was doing precisely that.” Zahra accepts the acknowledgement without making her repeat it.')),
 scene('The diagram with a missing hand','Mira brings a diagram and asks Zahra what is missing. “A hand here,” Zahra says. “And a person swearing quietly when this slips.” Mira reaches for a pencil.',
 ('Help them make the instructions usable by a beginner','Zahra points to the worker’s view. “Clamp this side. Keep the other hand behind the cutting edge. If the wood shifts, stop and reset it.” Mira writes each step separately, then asks Zahra to check whether the drawing shows the same sequence.'),
 ('Enjoy the unlikely partnership','Mira’s dry footnotes and Zahra’s exact demonstrations turn out to suit each other. Their argument about the swearing becomes a running joke.'),
 ('Ask them to credit the practical corrections by name','Mira writes Zahra’s name beside the amended figure. Zahra looks at it longer than she looks at the new diagram.')),
 scene('An authority in the footnote','Zahra catches Mira referring to her correction during another discussion. “You quoted me?” she asks. “You were the authority on the point,” Mira answers.',
 ('Ask how they decide when to trust a source now','Mira says she asks what experience the source can answer for. Zahra says she has become more willing to open a book that admits where it needs a teacher.'),
 ('Let Zahra enjoy being quoted','“Zahra, Defender of the Properly Supported Joint,” she proposes. Mira writes Zahra: practical correction beside the figure. “Your title exceeded the margin.” Zahra studies it. “Acceptable. I shall use the longer version at supper.”'),
 ('Point out that either of them may still be mistaken','“Obviously,” Zahra says. Mira agrees. The easy agreement is a better sign than any promise never to argue again.'))],
 {'curious':'Their revised diagram has already survived a beginner’s most inconvenient questions.','warm':'A note reading insert appropriate quiet swearing remains in the private draft, to their continuing delight.','candid':'Zahra’s named contribution is preserved beside the formal citation, with neither treated as decoration.'})

pair('iona-nyssara',['iona','nyssara'],'Trusting an unfamiliar method',[
 scene('The route through the threshold','Iona asks whether an instant crossing leaves a traveller enough time to understand where she has arrived. Nyssara answers the technical question, then notices that it was not the only question.',
 ('Ask Iona what she wants to preserve about a journey','“Orientation. The feeling that I can turn back.” Nyssara explains which parts a threshold can offer and which require an ordinary pause afterwards.'),
 ('Ask them to imagine a comfortable arrival together','They describe a clear landing place, a moment to look around and someone who does not immediately demand the next decision.'),
 ('Say a faster journey is not automatically everyone’s preference','Nyssara agrees. “A capability is not an instruction.” Iona looks relieved to hear it from her.')),
 scene('A map with room for hesitation','Iona sketches a threshold beside an ordinary road. Nyssara asks why the road remains so prominent. “Because a choice should be visible even when it is slower,” Iona says.',
 ('Encourage a plan that explains both methods clearly','They write separate descriptions, including what each traveller must know beforehand. Neither route is labelled the sensible one.'),
 ('Ask what would make them choose differently on a tired day','Iona admits she might welcome the shorter crossing. Nyssara admits she sometimes wants the walk. Their apparent opposition becomes less tidy.'),
 ('Ask them to leave the final decision to the traveller','They remove a suggested default from the sketch. “We can offer information without voting on someone else’s comfort,” Nyssara says.')),
 scene('An agreement about arrival','The two of them have stopped debating which journey is better and started debating what a welcome requires. Iona wants a clear destination. Nyssara wants room for the traveller to ask a question twice.',
 ('Ask them to explain the welcome they designed','Iona describes a clear landing with the destination written where an arriving traveller can see it. Nyssara adds a seat and a visible ordinary exit. “Explain where they are before asking where they want to go next.” It remains a proposal on paper; no facility has been commissioned.'),
 ('Enjoy their shared enthusiasm','They interrupt one another once, apologise at the same time, and laugh. The conversation has acquired a pace both can enjoy.'),
 ('Keep the plan optional, even after all that thought','“Yes,” Iona says. Nyssara adds, “Especially after all that thought. We are not owed a passenger.”'))],
 {'curious':'Both routes now have equally clear instructions, including the option to reconsider before departing.','warm':'Their margins contain personal reasons to walk and personal reasons not to, with neither list winning.','candid':'The traveller’s choice remains the final line, instead of a decision already made by the designers.'})

pair('tamsin-sabine',['tamsin','sabine'],'Hosting without performing',[
 scene('The guest list and the empty chair','Sabine has arranged names to make conversation flow. Tamsin has left a chair for someone unexpected. “A seating plan is not a locked gate,” Sabine says. “Then let us leave the gate visible,” Tamsin answers.',
 ('Ask what each hopes a guest will feel','Sabine wants nobody stranded. Tamsin wants nobody to feel uninvited. They discover that their plans began with the same fear from opposite sides.'),
 ('Suggest trying a deliberately informal table','Sabine moves one carefully placed name. Tamsin agrees that a newcomer might still appreciate an introduction. Neither abandons her care.'),
 ('Ask them not to arrange people without asking what they prefer','They decide to offer seats rather than assign them. Sabine admits that elegant planning can become a very polite command.')),
 scene('The compliment after supper','Sabine praises Tamsin for making everything look easy. Tamsin says, carefully, “I would rather you noticed that it was work.” Sabine puts down the list she was about to discuss.',
 ('Ask for a more specific acknowledgement','Sabine names the timing, the welcome and the missed chance for Tamsin to sit. Tamsin says the last observation matters most.'),
 ('Invite them both to be guests for a moment','Sabine chooses to impersonate a teapot in Tamsin’s guessing game. “I am frequently handled and insufficiently admired.” Tamsin asks whether she contains tea. Sabine answers, “Only when adequately prepared.” They dispute whether that counts as yes until both are laughing.'),
 ('Ask how future invitations can include their own enjoyment','Tamsin strikes out a second dessert. Sabine removes individual place cards. “I enjoy introductions more than arranging chairs,” Sabine says. “I enjoy sitting in one,” Tamsin replies. They keep the game and leave time to play it.')),
 scene('An invitation with two signatures','Tamsin and Sabine show you a note signed by them both. “Company requested,” Sabine reads. “Perfection not available,” Tamsin adds. The second line is also written down.',
 ('Ask how they divided the things they enjoy doing','Sabine will introduce people; Tamsin will choose the game. Both reserve the right to sit down.'),
 ('Accept the spirit of the invitation','They exchange a pleased look before either answers you. Their collaboration now includes the enjoyment they once forgot to plan.'),
 ('Remind them that a quiet evening counts too','“Then this may already be one,” Tamsin says. Sabine folds the unsigned spare invitations away.'))],
 {'curious':'Their thanks have become specific enough that neither has to guess whether the other saw the effort.','warm':'The guessing game now has a thoroughly unnecessary diplomatic vocabulary, supplied by Sabine.','candid':'Their next plan explicitly leaves time for both hosts to become ordinary company.'})

# Contextual conversations require actual saved evidence, not speculative narration.
REACTIONS={
'mira':('spell','After the working', 'Mira asks about a spell you have actually cast. “Did understanding what it would do change the experience of doing it? I used to think explanation would spoil wonder.”',
 ('Ask whether precision has changed her own sense of wonder','“Knowing why a lens bends the light does not make the image less lovely. It lets me notice the shape of the edge instead of calling the whole thing mysterious.” Mira smiles. “And when it fails, I have a better question than why the universe dislikes my diagram.”'),
 ('Tell her you wanted to share the moment with her','“Then I am glad you did not turn it straight into a report.” She asks what you noticed first, before the useful result.'),
 ('Say a useful spell can still feel ordinary','“Yes. We need not perform astonishment on demand.” She looks pleased by the freedom to discuss the work plainly.')),
'tamsin':('journey','The part after coming home','Tamsin waits until you have returned from a journey. “Would you like to tell it, or would you like to be home before you become a story?” She leaves the question open.',
 ('Say you are still tired even though the journey is over','“I understand. Coming back does not always make the tiredness disappear.” Tamsin leaves the kettle within reach. “Do you want to talk now, or begin with a cup and decide after?”'),
 ('Choose familiar company before an account of the journey','“Then a local controversy: handles facing out on the cup shelf, or all turned to the same side? I want to reach one without moving three.” Tamsin smiles. “You may defend the other arrangement. I shall ask you to demonstrate it.”'),
 ('Tell her you will choose when to discuss it','“Of course.” She changes the subject without becoming distant. You do not have to earn a welcome by delivering a story.')),
'iona':('journey','The journey and the report','Iona has read the practical record of a returned expedition. “That tells me what came home. It does not tell me what the journey was like for you.”',
 ('Talk about a decision rather than a discovery','“Which alternative were you considering, and what made you choose?” Iona opens a blank page rather than guessing from the inventory. “The result tells us what happened. I want to understand what you knew when you decided.”'),
 ('Ask about a journey she still remembers','“A ferryman redirected my map past his brother’s bakery. I discovered the detour when the river was nowhere in sight.” Iona smiles. “I corrected the road, kept the bakery marked and asked for directions from somebody who was not related to the baker.”'),
 ('Say you would rather leave the journey in the journal today','“Then the report can do its job.” She closes it and asks what you want from the rest of the evening.')),
'aurelia':('journey','Safe is not the whole answer','After your return, Aurelia starts to ask whether everyone is safe, then changes the question. “How are you finding being here again?”',
 ('Say it is hard to stop thinking about the next decision','“That is fair. You have been deciding the next step for everyone; being home does not remove the habit at once.” Aurelia sits with you. “I will ask one question: would company help, or would you prefer time alone?”'),
 ('Tell her her familiar presence helps','Her wings shift. “I can be familiar without standing guard. That is good to know.”'),
 ('Ask her not to check on you repeatedly','“One honest question, then room for your answer.” She nods. “Tell me if you want another.”')),
'neris':('spell','What the water did not decide','Neris has heard that the household has completed a casting. “People talk as if magic makes the choice for you. A working still needs someone to decide when it is worth using.”',
 ('Ask how she makes that decision','“First, name the result I want. Then ask whether a simpler method does the same job.” Neris turns her cup. “If I only need to see its colour, I can move it to the window. I enjoy magic, but I enjoy having enough sense to pick up a cup too.”'),
 ('Enjoy talking about a successful piece of work','“Which part pleased you most: understanding it, seeing it work, or having finished?” Neris smiles. “I often pretend the answer is understanding. After a stubborn design, finished has considerable charm.”'),
 ('Say convenience can be a sufficient reason','“Certainly. Every ordinary kindness need not pass an examination in grandeur.” She raises her cup to modest improvements.')),

'sabine':('spell','An easier answer','Sabine raises the subject of magic after a real household casting. “An easier conversation is not necessarily a more truthful one. I hope we will remember that when ease becomes available.”',
 ('Ask how she distinguishes reassurance from persuasion','“Whether I leave the other person room to give an answer I dislike.” She does not pretend the distinction is always comfortable.'),
 ('Tell her you would rather hear her unpolished opinion','“Then here it is: useful power deserves exact questions, including from someone fond of you.”'),
 ('Say persuasion is part of ordinary conversation too','“Indeed. That is why I distrust a neat division between innocent words and complicated magic. We should pay attention to both.”')),
'koharu':('spell','What remains handmade','After a casting, Koharu turns a small unfinished piece in her hands. “If a working can do part of this faster, I want to choose which part I still enjoy doing slowly.”',
 ('Ask which part she would keep for herself','“Fitting the pieces until I understand why they belong together.” She smiles. “You may magically tidy every shaving afterwards.”'),
 ('Tell her you value the time she chooses to put into things','“Choose is the useful word.” She returns to the piece without making slowness into an obligation.'),
 ('Say speed can make room for another pleasure','“Yes. I do not want to defend drudgery because it happens near craftsmanship.” She lays aside the dullest part of the explanation first.')),
'zahra':('spell','Strength without a contest','Zahra considers the news of a completed spell. “Someone will inevitably ask whether magic is stronger than a smith. I should like to ask why we are lifting the same thing competitively.”',
 ('Ask what cooperation would look like instead','“One person steadies, one person watches the fit. Neither needs an audience.” She seems delighted by this deeply unheroic arrangement.'),
 ('Invite her to make fun of the imaginary contest','“First contest: hold a crate overhead until everyone is bored. Second: carry it across the room without using the handles. Third: apologise to the person who made the handles.” Zahra smiles. “I award the prize to whoever fetches a trolley before the first round.”'),
 ('Ask whether she would miss being asked about her magic','Zahra takes the question seriously. “I enjoy a curious question. I dislike being asked for a demonstration before anyone asks my name.” A small ember settles between her fingertips. “Ask what I have been making. That usually leads somewhere better.”')),
'fenna':('journey','The version without embellishment','Fenna asks for the story of a completed journey. “Accurate version first. I will seek permission before introducing a spectacularly implausible bird.”',
 ('Give her the accurate version and ask what catches her interest','She notices an awkward pause you would have edited out. “That is where it starts sounding like people rather than a noticeboard.”'),
 ('Invite a clearly imaginary retelling afterwards','“In the entirely invented version, a bird larger than the gate demanded a map. It wanted the shortest route to an egg it had misplaced.” Fenna pauses. “We refused to guide it until it admitted the egg was a boulder. I am labelling this version fiction in very large letters.”'),
 ('Ask her to keep this one out of public storytelling','“Then it stays here.” She does not bargain for an anonymous version. The next tale she tells is her own.')),
'kaede':('journey','After the difficult choice','Kaede asks about a returned expedition. “I can discuss what you might do differently, if you want. I can also refrain. I have been informed this is an important skill.”',
 ('Invite questions about the alternatives you considered','“What did you know before choosing? Which alternative looked possible then?” Kaede waits rather than supplying her own verdict. “If we begin with the result, every wrong turning looks obvious. I would rather understand the decision you actually had.”'),
 ('Choose an evening that is not a debriefing','“Understood.” She asks whether you would like company over a game, making no attempt to turn the game into a field exercise.'),
 ('Tell her you have already judged yourself enough today','Her expression softens. “Then I will not add a second examiner.” She leaves room for the conversation to become ordinary.')),
'elowen':('journey','Care after the account','Elowen speaks with you after a journey has been brought home. “People sometimes answer how are you with an inventory. It is a useful inventory. It is not always the answer.”',
 ('Say you are glad to be home but do not feel cheerful yet','“Then I will not ask you to produce a cheerful ending.” Elowen pours water and sits. “Would you rather begin with what wore you out, or talk about something familiar first?”'),
 ('Ask for familiar company rather than advice','“A perfectly reasonable request.” She puts her notes aside before you have to ask a second time.'),
 ('Keep the account practical for now','She accepts the boundary. “If the other answer arrives later, it is still welcome.”')),
'nyssara':('ritual','Living beside a permanent working','After a lasting circle is completed, Nyssara asks what it means to keep a working active for the household. “Permanent should describe the inscription. It should not prevent us from asking whether we still want its effect.”',
 ('Ask how she would revisit that decision','“With the people who use the space, and without treating a changed mind as an insult to the maker.” She suggests asking the people who live alongside it.'),
 ('Enjoy the fact that the household made something lasting','“Yes. We are allowed to be pleased before beginning the next improvement.” She deliberately closes the notebook.'),
 ('Say constant reconsideration could become exhausting','“Then choose a sensible occasion to review it. Reflection need not be a permanent meeting.”')),
'sylva':('ritual','What changes around a circle','Sylva has noticed the household living with a completed ritual. “I wonder which changes we will stop noticing first. Not because they cease to matter, but because they become ordinary.”',
 ('Ask what she wants you to keep noticing','“Who uses it. Who finds it less helpful than expected. And whether anyone feels unable to say so.”'),
 ('Say you enjoy the household having more comfortable places to gather','“I like watching someone choose where to sit because the room is comfortable,” Sylva says. “If the working helps with that, good. If somebody prefers another room, I want to hear why before deciding they have failed to appreciate it.”'),
 ('Say a lasting effect should not decide how everyone lives','“Then we should keep asking one another.” She smiles. “An inscription cannot perform the whole work of being neighbours.”')),
}

GATHERINGS=[
 (['mira','tamsin'],'A supper with no report','Tamsin asks for one story that does not concern completed work. Mira immediately offers an unfinished book. “That is dangerously close,” Tamsin says. Mira insists the book has been unfinished for years and therefore qualifies.',
 ('Ask everyone for a small thing they enjoyed','“A marginal note that says ‘the horse cannot possibly know that’,” Mira offers. Tamsin chooses the first slice of a loaf with a crisp crust. “What did the horse know?” she asks. Mira admits she began reading from the complaint and has not reached its explanation.'),
 ('Say you enjoyed a few minutes with no errand to do','You mention enjoying a few minutes without an errand. “Did you sit down before someone found you?” Tamsin asks. Mira adds, “And did you spend the whole time deciding what to read?” They defend different ways of spending ten unclaimed minutes.'),
 ('Admit you do not feel talkative','“You may simply listen,” Tamsin says. Mira opens her unfinished book. “The hero disappeared for three chapters. I assumed a kidnapping. He was buying boots.” Tamsin asks whether they were good boots. “We are still awaiting the fitting,” Mira replies.')),
 (['fenna','kaede'],'Rules for a harmless game','Fenna proposes a guessing game. Kaede requests a complete explanation of the rules. Fenna admits some of them have not been invented yet. Kaede looks at you with profound but not unhappy suspicion.',
 ('Ask them to agree on the rules before the first round','They settle on a hidden object, five yes-or-no questions, and one guess. Fenna requests that an object may answer indignantly. Kaede agrees provided indignation still contains yes or no. “A severe restriction on my range,” Fenna says, delighted.'),
 ('Join the experimental version','Fenna’s chosen object is a wooden bird. Kaede asks whether it can fly. “Not without assistance.” Kaede objects that this is not yes or no. You agree the round was an experiment and add the missing rule: answer about the object itself, not the creature it depicts.'),
 ('Offer to watch the first round','Fenna answers that her object has wings but cannot fly. Kaede guesses an injured goose. Fenna reveals the wooden bird. “I dispute the fairness of the question,” Kaede says. Fenna offers a rematch with clearer rules; neither asks you to award the round.')),
 (['iona','sabine'],'Letters that will not be sent','Iona proposes writing one sentence you do not intend to send. Sabine asks whether it must be elegant. “It must be yours,” Iona says. The paper stays with its writer.',
 ('Write privately and share only what you choose','Sabine reads, “I was angry, and I wanted you to notice before I had to explain why.” She folds the sheet again. Iona keeps her own line private. Nobody reaches for another person’s paper or asks for a name.'),
 ('Suggest writing a fond note to the household instead','Iona writes, “I like coming home to people who ask about more than the road.” Sabine suggests, “Thank you for the evenings after the work is done.” They combine the two, argue about a comma and leave the note as a draft on the table.'),
 ('Decline to write but stay for the company','Iona puts your blank sheet away without comment. Sabine observes that declining an exercise may itself be an admirably concise statement.')),
 
 (['koharu','zahra'],'Objects with no impressive value','Koharu brings a worn toy; Zahra brings an ordinary fastening from an early piece of work. Neither object would win an exhibition. Both owners are unusually careful placing them on the table.',
 ('Ask what each object lets them remember','Koharu turns over the toy cart. “I took it apart to learn why the wheel turned only one way. Then I had to put it back together before I could play.” Zahra shows a misaligned fastening. “My first. I kept it because I remember how certain I was that measuring twice would be excessive.”'),
 ('Say a familiar object can matter even when a newer one works better','You say you value a possession because it is familiar in your hand. “That matters,” Zahra says. Koharu points to the worn edge of her toy. “I would not sand that smooth now. It is where I held it.”'),
 ('Ask before handling either keepsake','Koharu lets you turn the toy over and points out the bent fitting. Zahra keeps the fastening in her palm. “The pin is loose; I do not want it on the floor.” She shows you how the two holes fail to line up without handing it over.')),
 (['nyssara','sylva','elowen'],'An evening without improvement','Elowen proposes an evening in which nobody recommends a remedy. Nyssara asks whether this includes technical improvements. Sylva asks whether the proposal itself counts as an improvement. The experiment is in immediate difficulty.',
 ('Keep the spirit of the idea without policing every sentence','Nyssara remarks that the chair would be better nearer the lamp, then pauses. Elowen laughs. “Move it if you like. I meant nobody has to leave with an improvement plan.” Sylva claims the patch of warm stone the chair has uncovered. “I have benefited already.”'),
 ('Ask what each enjoys simply as it is','Nyssara chooses a line from her book: “He knew the road so well he forgot to ask where she wished to go.” Sylva chooses copper leaves against grey stone. Elowen rubs lemon balm between her fingers. “The scent. No prescription follows.”'),
 ('Say advice is welcome when someone actually asks for it','“Then the rule is a question,” Elowen says. Nyssara approves the efficient design; Sylva points out that you have all immediately improved it.')),
]

def catalogue():
    rows={}
    for who,arc in PERSONAL.items():
        for i,d in enumerate(arc):rows[f'personal:{who}:{i}']={**d,'participants':[who],'category':'personal','arc':who,'stage':i,'previous':f'personal:{who}:{i-1}' if i else None}
    for key,arc in PAIRS.items():
        for i,d in enumerate(arc['scenes']):rows[f'pair:{key}:{i}']={**d,'participants':arc['participants'],'category':'pairs','arc':key,'stage':i,'previous':f'pair:{key}:{i-1}' if i else None,'relationship':arc['label'],**({'branches':arc['branches']} if i==2 else {})}
    for who,(trigger,title,opening,*choices) in REACTIONS.items():rows[f'reaction:{who}']={**scene(title,opening,*choices),'participants':[who],'category':'reactions','arc':who,'stage':0,'previous':None,'trigger':trigger}
    for i,(people,title,opening,*choices) in enumerate(GATHERINGS):rows[f'gathering:{i}']={**scene(title,opening,*choices),'participants':people,'category':'gatherings','arc':str(i),'stage':0,'previous':None}
    return rows
PERSONAL_BRANCHES={
'mira': {'curious':'Mira has left the most troublesome sentence underlined instead of correcting it.', 'warm':'The passage you read together now has a note in the margin: requires two unconvincing actors.', 'candid':'Your disagreement remains on the page. Mira has resisted the temptation to add a final rebuttal.'},
'tamsin': {'curious':'Tamsin has written down the ridiculous game she wanted to play, including one rule that makes her laugh every time.', 'warm':'Tamsin remembers being able to choose the conversation and asks whether you would like another story.', 'candid':'Tamsin has begun saying when she wants company rather than looking for a useful task to bring along.'},
'iona': {'curious':'Iona has kept a copy of the letter that explained why she stayed without promising a departure.', 'warm':'Iona refers to your small celebration as the evening of not packing, with increasing affection.', 'candid':'Iona returns to your difficult question. “I checked. Today I am staying because I want to, not because I am afraid to answer a letter.”'},
'aurelia': {'curious':'Aurelia recalls the reminder you discussed: her name, followed by a question she can actually answer.', 'warm':'Aurelia thanks you for keeping her request private rather than making it a lesson for the household.', 'candid':'Aurelia begins plainly: “I would like company. I decided not to make you guess.”'},
'neris': {'curious':'Neris taps the rhythm you worked out together before beginning the conversation.', 'warm':'The invented duck has acquired another verse. Neris warns you that its opinions have not improved.', 'candid':'“No lesson today,” Neris says. “I wanted to see you. That is the whole proposal.”'},

'sabine': {'curious':'Sabine repeats the apology she offered: “You were trying to help. I made you the joke. I am sorry.” She says she waited for the answer this time.', 'warm':'“Offer, not secure acceptance,” Sabine repeats. “Your distinction proved annoyingly useful.”', 'candid':'Sabine acknowledges your warning: she let the other person remain annoyed instead of trying to win a warmer response.'},
'koharu': {'curious':'Koharu has kept the history of the crooked detail with the repair notes, where the next maker will find it.', 'warm':'Koharu makes a show of placing every tool out of reach before sitting down with you.', 'candid':'Koharu has drawn two safe repair options. “You asked what I would do. I thought I should have an answer that still leaves a choice.”'},
'zahra': {'curious':'Zahra has brought a second small mechanism because you asked to understand the difficult part of the first.', 'warm':'Zahra remembers your delight more vividly than the object itself. She says so, then looks faintly embarrassed.', 'candid':'Zahra tries the direct request you agreed on: “Another subject today. I have exhausted my own patience with the strong-person jokes.”'},
'fenna': {'curious':'Fenna asks about the complicated answer you gave her before offering a new subject of her own.', 'warm':'Fenna has saved one particularly good joke. “It may wait. I learned that it will not dissolve if I ask a real question first.”', 'candid':'Fenna is relieved that honesty has not required a permanent solemn voice. The laughter and the questions now have separate room.'},
'kaede': {'curious':'Kaede remembers the unexpected move as a pleasure rather than immediately explaining how she should have prevented it.', 'warm':'Kaede proposes another game under the no-instruction-afterwards agreement, which she has apparently taken very seriously.', 'candid':'Kaede asks before offering an observation about your play. Your earlier request has become a habit she is practising.'},
'elowen': {'curious':'Elowen remembers being able to say she was disappointed without being told how to correct the feeling.', 'warm':'“That was good company,” Elowen says of your unhurried evening. She does not attach an improvement plan to it.', 'candid':'Elowen returns your earlier uncertainty with her own: “I do not have the right answer ready. I would still like to talk.”'},
'nyssara': {'curious':'Nyssara has marked the junction you discussed, including the question that made her reconsider it.', 'warm':'Nyssara admits she enjoyed being watched with interest rather than suspicion, then asks what has caught your attention today.', 'candid':'Nyssara refers to the boundary you agreed to respect and moves comfortably into a different subject.'},
'sylva': {'curious':'Sylva has brought two fallen leaves for the colour picture she described. One is yellow; the other has a copper edge.', 'warm':'The bare pot remains where it was. Sylva greets you without feeling obliged to report new growth.', 'candid':'Sylva tells you directly that she wants company today. “I thought I should spare you the difficult business of interpreting a leaf.”'},
}
CATALOGUE=catalogue()
for who,branches in PERSONAL_BRANCHES.items():
    CATALOGUE[f'personal:{who}:2']['branches']=branches


EVERYDAY={
'mira':scene('The worst opening sentence','Mira has found a novel that begins with three consecutive weather reports. “By the second paragraph I knew the wind better than the protagonist.” She wants to know whether you would continue reading.',
 ('Defend the weather as a promising main character','“It has certainly shown more range.” Mira reads in a tragic voice: “Rain beat against the windows, as though it too regretted the engagement.” She lowers the page. “At last. Somebody objects to the wedding.”'),
 ('Invent a worse first sentence together','You begin, “When seven cousins discovered the locked door—” Mira continues, “—only the spoon knew which of them had brought soup.” She writes it down. “No. We have made it interesting. The spoon deserves a chapter.”'),
 ('Admit you enjoy a slow beginning','Mira considers the page again. “Perhaps I wanted a different sort of evening from the author.” She lends you the argument, rather than declaring the book beyond rescue.')),
'tamsin':scene('A scandal concerning raisins','Tamsin asks whether raisins belong in a savoury loaf with the gravity of a person discussing castle law. Her tail gives away that she is enjoying the dispute before it has begun.',
 ('Ask who introduced this controversy','“Someone said everybody likes a surprise. I maintain that a surprise should not resemble an unexpected raisin.” She has evidently prepared her case.'),
 ('Declare yourself willing to conduct a very small taste trial','“Two small loaves when we next bake. Same dough, one with raisins, one without.” Tamsin considers. “Blindfold the raisins so they cannot influence the verdict.” Her tail gives away how pleased she is with the proposal.'),
 ('Defend the raisins','“Then I shall save you the controversial end.” She laughs. Your difference in taste appears likely to make future meals more entertaining.')),
'iona':scene('A city drawn from memory','Iona tries to draw a city she visited long ago and discovers that every street leads to the same bakery. “This is a reliable record of my priorities, at least.”',
 ('Ask what else she remembers about the bakery','“A bell that rang after you had already come in. The owner always said it was considering the matter.” Her map gains a delayed bell.'),
 ('Draw a place you remember beside hers','Your account follows landmarks more personal than accurate. Iona names the combined sheet an atlas of where we were paying attention.'),
 ('Ask whether either of you could navigate with this map','“Certainly. We would be lost within minutes, but extremely well prepared to discuss pastry.” She leaves it gloriously uncorrected.')),
'aurelia':scene('The bird that challenged the lantern','Aurelia describes a small bird that treated a lantern’s reflection as a rival. “It was determined. Entirely mistaken, but determined.” She then admits she saluted it before noticing anyone was watching.',
 ('Ask whether the bird accepted the salute','“It attacked the reflection again. I interpreted that as a refusal to stand down.” Her solemn expression lasts almost to the end.'),
 ('Tell her you would have liked to see it','“The bird was a more commanding presence than I was.” She tries the salute again, this time with a smile she makes no effort to hide.'),
 ('Suggest the reflection may have started it','Aurelia considers this with exaggerated fairness. “I had only one witness. My investigation was clearly incomplete.”')),
'neris':scene('A song with too many verses','Neris remembers a river song whose verses were added by every town along the water. “By the time it reached the sea, nobody could finish it before supper.” She knows three incompatible beginnings.',
 ('Ask to hear the oldest beginning she knows','Neris taps twice, pauses, then sings: “One boat at the landing, one boot on the stair; the ferryman swore he had left a full pair.” She looks up. “The next town blamed the fish. I consider that a serious failure of imagination.”'),
 ('Offer a verse about the castle','You propose, “Three doors in the castle and none lead to tea.” Neris answers, “Then knock at the fourth and be welcomed by me.” She taps the line again. “One extra beat. An acceptable price for hospitality.”'),
 ('Choose the shortest version on principle','“Boat arrived. Boot missing. Ferryman declined comment.” Neris folds her hands. “The shortest version. Entirely unsuitable for dancing, but we shall reach supper on time.”')),

'sabine':scene('A truly dreadful ghost story','Sabine offers a ghost story in which the haunting consists entirely of misplaced correspondence. “The apparition was eventually accused of being an inefficient secretary.” She is waiting for your objection.',
 ('Ask what the ghost wanted','“Acknowledgement of receipt. A tragic and unfulfilled ambition.” She folds an imaginary letter with grave precision.'),
 ('Demand an appropriately melodramatic performance','“Reeeeceived?” Sabine moans as the ghost, then straightens into the secretary. “In triplicate, please.” Back to the ghost: “I have haunted this desk for thirty years.” The secretary sighs. “Then you know the procedure.”'),
 ('Defend the ghost’s right to a reply','“Then you are the sympathetic figure.” Sabine continues the story: “You turn the envelope over. The reply has been on the back for thirty years. The ghost reads ‘Approved’, says ‘At last’, and leaves you with an impossible number of unfiled receipts.”')),
'koharu':scene('The drawer full of almost useful things','Koharu admits she keeps a drawer of pieces that might become useful. “One of them has been almost useful for six years. We have grown attached.”',
 ('Ask her to describe the oldest piece','“A bent fitting from a toy cart. I dismantled it because the wheel turned only one way.” Koharu traces the shape in her palm. “A little tooth caught against this bend. I spent the afternoon making it roll backwards. Then I had to discover why a cart rolling off the table was less desirable.”'),
 ('Invent improbable uses for its contents','You propose a hat for a very particular beetle. Koharu improves the fastening before realising that she has accepted the entire premise.'),
 ('Ask whether almost useful is another word for keepsake','“Sometimes.” She smiles. “Please do not tell the drawer. It believes it is a professional collection.”')),
'zahra':scene('A lullaby with an alarming chorus','Zahra remembers a lullaby with a chorus about thunder. “It was meant to reassure us. I preferred the quiet verse about sheep.” Her attempt to whisper the chorus is wonderfully unsuccessful.',
 ('Ask for the sheep verse','Zahra lowers her voice: “Three sheep under the willow, one lamb against the gate; the shepherd counts them twice because the moon has made him late.” She smiles. “No thunder. No frightened livestock. A much better arrangement for sleeping.”'),
 ('Join in with whatever words you can guess','You give the third sheep eight legs. Zahra sings, “The shepherd counted thirty feet—” then stops. “No. We have made a bookkeeping problem.” She laughs. “Start again before we frighten the lamb.”'),
 ('Suggest that thunder is a questionable bedtime strategy','“An opinion I held firmly at the time.” She says the next generation deserves a version with less weather and more sensible sheep.')),
'fenna':scene('Three rumours about a perfectly ordinary hill','Fenna offers three local explanations for a hill’s peculiar name. One involves a lost crown, one a sleeping giant and one a farmer with an unfortunate surname. “You may choose which deserves to be true.”',
 ('Choose the farmer and ask for the least glamorous details','“The farmer put his fence along the wrong boundary. His neighbour moved it back every morning. They agreed to call the hill Disputed until one produced the deed.” Fenna pauses. “Neither wanted to pay for a copy. The fence lasted longer than their argument.”'),
 ('Invent a fourth explanation together','You propose that the hill was named for a picnic carried away by wind. Fenna adds, “One pie reached the summit before the guests. They climbed up to reclaim it and declared the expedition a success.” She points at you. “Your picnic, my pie. Entirely invented.”'),
 ('Ask which story she actually believes','“The farmer. But I would ask someone who lived there before putting it on a map.” She enjoys a story without requiring you to mistake it for evidence.')),
'kaede':scene('The dignity of falling over','Kaede recalls slipping while demonstrating an especially graceful turn. “I landed correctly,” she insists. Then, after a pause: “In a basket.”',
 ('Ask whether the basket survived','“It showed excellent structural discipline.” Her expression finally breaks. “I was less successful at remaining impressive.”'),
 ('Share an undignified mishap of your own','She listens with growing amusement and offers no corrective technique. You are exchanging stories, not incident reports.'),
 ('Argue that landing in the basket demonstrates remarkable precision','“An interpretation I wish I had thought of at the time.” She borrows it, with your permission, for any future telling.')),
'elowen':scene('An herb with no respectable purpose','Elowen names a plant she likes solely because its scent reminds her of a warm wall. “People find this disappointingly unclinical. I think walls have been undervalued.”',
 ('Ask her to describe the place she remembers','“A low wall outside my teacher’s door. Lemon balm beside it, stone still warm after the shade reached the path. I could hear my teacher arguing with the cat indoors.” Elowen smiles. “The cat usually won by refusing to answer. I remember that whenever someone calls the place peaceful.”'),
 ('Tell her a scent you associate with comfort','She asks about the place attached to it rather than searching for a medicinal property. The conversation stays pleasantly personal.'),
 ('Champion the cause of unclinical pleasures','“A neglected field with excellent prospects.” She suggests that the household pursue it without creating an examination.')),
'nyssara':scene('A signature hidden in a joke','Nyssara shows you a practice flourish that resembles an excessively offended spider. “It began as a mistake. I have become rather fond of its opinion.”',
 ('Ask what offended the spider','“Poor spacing. Unjustified confidence. Possibly the entire preceding sentence.” Her dry delivery suggests the spider has inherited its maker’s tastes.'),
 ('Draw an equally opinionated creature beside it','She examines your contribution as though assessing a serious commission, then adds a tiny chair so the creatures may argue comfortably.'),
 ('Suggest keeping it out of official instructions','“Naturally. I cannot have the spider taking responsibility for work it has not reviewed.” She keeps the doodle for company instead.')),
'sylva':scene('The most interesting patch of wall','Sylva asks whether you have noticed a small patch of lichen. “It looks like a very important person in a very bad hat. I have been waiting to tell someone.”',
 ('Ask to hear the important person’s imaginary complaints','The hat is damp, the wall is unfashionable and passing birds are insufficiently respectful. Sylva gives the lichen a surprisingly imperious voice.'),
 ('Offer another shape you can see in it','Your interpretation changes the hat into a boat. Sylva turns her head and laughs. “Now I cannot unsee it. You have demoted a dignitary into transport.”'),
 ('Admit that you only see lichen','“Then I shall enjoy having a private acquaintance.” She does not insist that you see what she sees, but is pleased you looked.')),
}
for who,d in EVERYDAY.items():
    CATALOGUE[f'everyday:{who}']={**d,'participants':[who],'category':'everyday','arc':who,'stage':0,'previous':None}
